import math

def bsgs(a={{a}}, b={{b}}, m={{m}}):
    a %= m; b %= m; n = int(math.isqrt(m)) + 1
    table = {}
    cur = b
    for j in range(n+1):
        table[cur] = j
        cur = cur * a % m
    an = pow(a, n, m); cur = 1
    for i in range(1, n+1):
        cur = cur * an % m
        if cur in table:
            x = i*n - table[cur]
            if x > 0: return x
    return -1
